var item = $input.first().json;
var msg = String(item.chatInput || '').trim();
var sheetId = '';
var m1 = msg.match(new RegExp('\/spreadsheets\/d\/([a-zA-Z0-9_-]{20,})'));
if (m1) { sheetId = m1[1]; }
if (!sheetId) {
  var m2 = msg.match(new RegExp('(?:sheet id|sheet)[:\s]+([a-zA-Z0-9_-]{20,})', 'i'));
  if (m2) { sheetId = m2[1]; }
}
if (!sheetId) {
  var m3 = msg.match(new RegExp('([a-zA-Z0-9_-]{40,})'));
  if (m3) { sheetId = m3[1]; }
}
return [{ json: { sheetId: sheetId, chatInput: String(item.chatInput || ''), sessionId: String(item.sessionId || '') } }];

var rows = $input.all().map(function(item) { return item.json; });
if (!rows || rows.length === 0) {
  return [{json:{emailHtml:'<p>No data found.</p>',chatSummary:'No data found.',success:false}}];
}
var columns = Object.keys(rows[0]);
var totalRows = rows.length;
function findCol(patterns) {
  return columns.find(function(c){return patterns.some(function(p){return c.toLowerCase().indexOf(p.toLowerCase())!==-1;});});
}
var revenueCol=findCol(['revenue','amount','total','sales','price','value','cost']);
var categoryCol=findCol(['category','type','product_type','item_type','segment','group']);
var regionCol=findCol(['region','country','location','area','zone','city','state']);
var statusCol=findCol(['status','state','condition','stage','fulfillment']);
var nameCol=findCol(['name','customer','client','user','product','title','item']);
var quantityCol=findCol(['quantity','qty','units','volume']);
var seen={};var dupCount=0;var cleanRows=[];
rows.forEach(function(row){var key=JSON.stringify(row);if(seen[key]){dupCount++;}else{seen[key]=true;cleanRows.push(row);}});
var nullCounts={};columns.forEach(function(col){nullCounts[col]=0;});
rows.forEach(function(row){columns.forEach(function(col){var v=row[col];if(v===null||v===undefined||v===''||v==='N/A'||v==='null')nullCounts[col]++;});});
var nullIssues=[];Object.keys(nullCounts).forEach(function(col){if(nullCounts[col]>0)nullIssues.push(col+': '+nullCounts[col]+' missing');});
var totalRevenue=0;var revenues=[];var catMap={};var regionMap={};var statusMap={};var totalQty=0;
cleanRows.forEach(function(row){
  if(revenueCol){var rev=parseFloat(row[revenueCol]);if(!isNaN(rev)){totalRevenue+=rev;revenues.push(rev);}}
  if(quantityCol){var q=parseFloat(row[quantityCol]);if(!isNaN(q))totalQty+=q;}
  if(categoryCol){var cat=String(row[categoryCol]||'Unknown');if(!catMap[cat])catMap[cat]={count:0,revenue:0};catMap[cat].count++;if(revenueCol){var rv=parseFloat(row[revenueCol]);if(!isNaN(rv))catMap[cat].revenue+=rv;}}
  if(regionCol){var reg=String(row[regionCol]||'Unknown');if(!regionMap[reg])regionMap[reg]={count:0,revenue:0};regionMap[reg].count++;if(revenueCol){var rv2=parseFloat(row[revenueCol]);if(!isNaN(rv2))regionMap[reg].revenue+=rv2;}}
  if(statusCol){var st=String(row[statusCol]||'Unknown');if(!statusMap[st])statusMap[st]={count:0,revenue:0};statusMap[st].count++;if(revenueCol){var rv3=parseFloat(row[revenueCol]);if(!isNaN(rv3))statusMap[st].revenue+=rv3;}}
});
var avgRevenue=revenues.length>0?(totalRevenue/revenues.length):0;
var sortedRevs=revenues.slice().sort(function(a,b){return a-b;});
var midIdx=Math.floor(sortedRevs.length/2);
var medRevenue=sortedRevs.length>0?(sortedRevs.length%2!==0?sortedRevs[midIdx]:(sortedRevs[midIdx-1]+sortedRevs[midIdx])/2):0;
var maxRevenue=revenues.length>0?Math.max.apply(null,revenues):0;
var minRevenue=revenues.length>0?Math.min.apply(null,revenues):0;
var catEntries=Object.keys(catMap).map(function(k){return{name:k,count:catMap[k].count,revenue:catMap[k].revenue};}).sort(function(a,b){return b.revenue-a.revenue;});
var regEntries=Object.keys(regionMap).map(function(k){return{name:k,count:regionMap[k].count,revenue:regionMap[k].revenue};}).sort(function(a,b){return b.revenue-a.revenue;});
var stEntries=Object.keys(statusMap).map(function(k){return{name:k,count:statusMap[k].count,revenue:statusMap[k].revenue};}).sort(function(a,b){return b.count-a.count;});
var topPerformers=[];
if(revenueCol&&nameCol&&nameCol!==revenueCol){var sortedRows=cleanRows.filter(function(r){return!isNaN(parseFloat(r[revenueCol]));}).sort(function(a,b){return parseFloat(b[revenueCol])-parseFloat(a[revenueCol]);});topPerformers=sortedRows.slice(0,5).map(function(r){return{name:r[nameCol],revenue:parseFloat(r[revenueCol])};});}
function fmtRev(v){return '$'+parseFloat(v).toFixed(2);}
function pct(v,total){return total>0?((v/total)*100).toFixed(1)+'%':'N/A';}
function barRow(label,rev,maxRev,badge,color){var barW=maxRev>0?Math.round((rev/maxRev)*100):0;var out='<tr>';out+='<td style="width:130px;padding:5px 10px 5px 0;font-size:13px;color:#444;font-family:Arial,sans-serif;white-space:nowrap;">'+label+'</td>';out+='<td style="padding:5px 8px;"><div style="background:#ecf0f1;border-radius:4px;height:22px;overflow:hidden;"><div style="background:'+color+';width:'+barW+'%;height:100%;border-radius:4px;"></div></div></td>';out+='<td style="width:200px;padding:5px 0 5px 10px;font-size:13px;font-weight:bold;color:#2c3e50;font-family:Arial,sans-serif;white-space:nowrap;">'+fmtRev(rev)+' <span style="color:#888;font-weight:normal;">('+badge+')</span></td>';out+='</tr>';return out;}
var html='';
html+='<div style="max-width:700px;margin:0 auto;background:#fff;font-family:Arial,sans-serif;">';
html+='<div style="background:linear-gradient(135deg,#2c3e50,#3498db);padding:32px 28px;border-radius:10px 10px 0 0;"><h1 style="color:#fff;margin:0;font-size:24px;">Data Analysis Report</h1><p style="color:rgba(255,255,255,0.8);margin:8px 0 0 0;font-size:14px;">Generated by n8n Data Analyst Agent</p></div>';
html+='<div style="padding:28px;">';
html+='<h2 style="color:#2c3e50;font-size:17px;border-bottom:2px solid #3498db;padding-bottom:8px;margin:0 0 16px 0;">1. Data Preprocessing Summary</h2>';
html+='<table style="width:100%;border-collapse:collapse;font-size:13px;margin-bottom:24px;">';
html+='<tr><th style="background:#f8f9fa;border:1px solid #ddd;padding:10px 12px;text-align:left;">Metric</th><th style="background:#f8f9fa;border:1px solid #ddd;padding:10px 12px;text-align:left;">Value</th></tr>';
html+='<tr><td style="border:1px solid #ddd;padding:9px 12px;">Total Rows (Original)</td><td style="border:1px solid #ddd;padding:9px 12px;font-weight:bold;">'+totalRows+'</td></tr>';
html+='<tr style="background:#fafafa;"><td style="border:1px solid #ddd;padding:9px 12px;">Rows After Deduplication</td><td style="border:1px solid #ddd;padding:9px 12px;font-weight:bold;">'+cleanRows.length+'</td></tr>';
html+='<tr><td style="border:1px solid #ddd;padding:9px 12px;">Duplicates Removed</td><td style="border:1px solid #ddd;padding:9px 12px;font-weight:bold;color:'+(dupCount>0?'#e74c3c':'#27ae60')+';">'+dupCount+'</td></tr>';
html+='<tr style="background:#fafafa;"><td style="border:1px solid #ddd;padding:9px 12px;">Columns Detected</td><td style="border:1px solid #ddd;padding:9px 12px;">'+columns.join(', ')+'</td></tr>';
html+='<tr><td style="border:1px solid #ddd;padding:9px 12px;">Missing / Null Values</td><td style="border:1px solid #ddd;padding:9px 12px;">'+(nullIssues.length>0?nullIssues.join('; '):'None detected')+'</td></tr>';
html+='<tr style="background:#fafafa;"><td style="border:1px solid #ddd;padding:9px 12px;">Completeness Score</td><td style="border:1px solid #ddd;padding:9px 12px;font-weight:bold;color:#27ae60;">'+pct(cleanRows.length,totalRows)+'</td></tr>';
html+='</table>';
html+='<h2 style="color:#2c3e50;font-size:17px;border-bottom:2px solid #3498db;padding-bottom:8px;margin:0 0 16px 0;">2. Key Performance Indicators</h2>';
html+='<table style="width:100%;border-collapse:collapse;margin-bottom:24px;"><tr>';
var kpis=[{label:'Total Records',value:cleanRows.length.toString(),bg:'#3498db'},{label:'Total Revenue',value:revenueCol?fmtRev(totalRevenue):'N/A',bg:'#27ae60'},{label:'Avg Order Value',value:revenueCol?fmtRev(avgRevenue):'N/A',bg:'#e67e22'},{label:'Total Units Sold',value:quantityCol?totalQty.toString():'N/A',bg:'#9b59b6'}];
kpis.forEach(function(k){html+='<td style="width:25%;padding:6px;"><div style="background:'+k.bg+';border-radius:10px;padding:16px 10px;text-align:center;"><div style="color:rgba(255,255,255,0.85);font-size:11px;text-transform:uppercase;letter-spacing:1px;margin-bottom:6px;">'+k.label+'</div><div style="color:#fff;font-size:20px;font-weight:bold;">'+k.value+'</div></div></td>';});
html+='</tr></table>';
if(revenueCol&&revenues.length>0){html+='<h2 style="color:#2c3e50;font-size:17px;border-bottom:2px solid #3498db;padding-bottom:8px;margin:0 0 16px 0;">3. Revenue Statistics</h2>';html+='<table style="width:100%;border-collapse:collapse;font-size:13px;margin-bottom:24px;">';html+='<tr><td style="border:1px solid #ddd;padding:9px 12px;">Total Revenue</td><td style="border:1px solid #ddd;padding:9px 12px;font-weight:bold;color:#27ae60;">'+fmtRev(totalRevenue)+'</td></tr>';html+='<tr style="background:#fafafa;"><td style="border:1px solid #ddd;padding:9px 12px;">Average Order Value</td><td style="border:1px solid #ddd;padding:9px 12px;font-weight:bold;">'+fmtRev(avgRevenue)+'</td></tr>';html+='<tr><td style="border:1px solid #ddd;padding:9px 12px;">Median Order Value</td><td style="border:1px solid #ddd;padding:9px 12px;font-weight:bold;">'+fmtRev(medRevenue)+'</td></tr>';html+='<tr style="background:#fafafa;"><td style="border:1px solid #ddd;padding:9px 12px;">Highest Single Order</td><td style="border:1px solid #ddd;padding:9px 12px;">'+fmtRev(maxRevenue)+'</td></tr>';html+='<tr><td style="border:1px solid #ddd;padding:9px 12px;">Lowest Single Order</td><td style="border:1px solid #ddd;padding:9px 12px;">'+fmtRev(minRevenue)+'</td></tr>';html+='</table>';}
if(catEntries.length>0){var maxCatRev=catEntries[0].revenue;html+='<h2 style="color:#2c3e50;font-size:17px;border-bottom:2px solid #3498db;padding-bottom:8px;margin:0 0 16px 0;">4. Revenue by Category</h2>';html+='<table style="width:100%;border-collapse:collapse;margin-bottom:24px;">';catEntries.forEach(function(cat){html+=barRow(cat.name,cat.revenue,maxCatRev,pct(cat.revenue,totalRevenue),'#3498db');});html+='</table>';}
if(regEntries.length>0){var maxRegRev=regEntries[0].revenue;html+='<h2 style="color:#2c3e50;font-size:17px;border-bottom:2px solid #3498db;padding-bottom:8px;margin:0 0 16px 0;">5. Revenue by Region</h2>';html+='<table style="width:100%;border-collapse:collapse;margin-bottom:24px;">';regEntries.forEach(function(reg){html+=barRow(reg.name,reg.revenue,maxRegRev,reg.count+' orders','#2ecc71');});html+='</table>';}
if(stEntries.length>0){html+='<h2 style="color:#2c3e50;font-size:17px;border-bottom:2px solid #3498db;padding-bottom:8px;margin:0 0 16px 0;">6. Order Status Breakdown</h2>';html+='<table style="width:100%;border-collapse:collapse;font-size:13px;margin-bottom:24px;">';html+='<tr><th style="background:#f8f9fa;border:1px solid #ddd;padding:10px 12px;text-align:left;">Status</th><th style="background:#f8f9fa;border:1px solid #ddd;padding:10px 12px;text-align:right;">Orders</th><th style="background:#f8f9fa;border:1px solid #ddd;padding:10px 12px;text-align:right;">Share</th><th style="background:#f8f9fa;border:1px solid #ddd;padding:10px 12px;text-align:right;">Revenue</th></tr>';stEntries.forEach(function(st,idx){var sl=st.name.toLowerCase();var badge=(sl.indexOf('complet')!==-1||sl.indexOf('done')!==-1||sl.indexOf('deliver')!==-1||sl.indexOf('success')!==-1)?'#27ae60':(sl.indexOf('pend')!==-1||sl.indexOf('process')!==-1)?'#e67e22':(sl.indexOf('cancel')!==-1||sl.indexOf('fail')!==-1||sl.indexOf('return')!==-1)?'#e74c3c':'#3498db';var bg=idx%2===0?'#fff':'#fafafa';html+='<tr style="background:'+bg+';">';html+='<td style="border:1px solid #ddd;padding:9px 12px;"><span style="background:'+badge+';color:#fff;padding:3px 10px;border-radius:12px;font-size:12px;">'+st.name+'</span></td>';html+='<td style="border:1px solid #ddd;padding:9px 12px;text-align:right;">'+st.count+'</td>';html+='<td style="border:1px solid #ddd;padding:9px 12px;text-align:right;">'+pct(st.count,cleanRows.length)+'</td>';html+='<td style="border:1px solid #ddd;padding:9px 12px;text-align:right;font-weight:bold;">'+(revenueCol?fmtRev(st.revenue):'N/A')+'</td>';html+='</tr>';});html+='</table>';}
if(topPerformers.length>0){html+='<h2 style="color:#2c3e50;font-size:17px;border-bottom:2px solid #3498db;padding-bottom:8px;margin:0 0 16px 0;">7. Top 5 Performers</h2>';html+='<table style="width:100%;border-collapse:collapse;font-size:13px;margin-bottom:24px;">';html+='<tr><th style="background:#f8f9fa;border:1px solid #ddd;padding:10px 12px;text-align:center;width:60px;">Rank</th><th style="background:#f8f9fa;border:1px solid #ddd;padding:10px 12px;text-align:left;">Name</th><th style="background:#f8f9fa;border:1px solid #ddd;padding:10px 12px;text-align:right;">Revenue</th></tr>';topPerformers.forEach(function(p,i){var bg=i%2===0?'#fff':'#fafafa';html+='<tr style="background:'+bg+';">';html+='<td style="border:1px solid #ddd;padding:9px 12px;text-align:center;font-weight:bold;">#'+(i+1)+'</td>';html+='<td style="border:1px solid #ddd;padding:9px 12px;">'+p.name+'</td>';html+='<td style="border:1px solid #ddd;padding:9px 12px;text-align:right;font-weight:bold;color:#27ae60;">'+fmtRev(p.revenue)+'</td>';html+='</tr>';});html+='</table>';}
html+='<div style="background:#eaf4fb;border-left:4px solid #3498db;border-radius:0 8px 8px 0;padding:18px 20px;margin-bottom:24px;"><h3 style="color:#2c3e50;font-size:15px;margin:0 0 12px 0;">Key Insights</h3><ul style="margin:0;padding-left:18px;">';
if(revenueCol&&revenues.length>0){html+='<li style="font-size:13px;color:#333;margin-bottom:8px;line-height:1.6;">Total revenue of '+fmtRev(totalRevenue)+' across '+cleanRows.length+' orders (avg '+fmtRev(avgRevenue)+' per order)</li>';}
if(catEntries.length>0&&revenueCol){var topCat=catEntries[0];html+='<li style="font-size:13px;color:#333;margin-bottom:8px;line-height:1.6;">Top category: <strong>'+topCat.name+'</strong> — '+fmtRev(topCat.revenue)+' ('+pct(topCat.revenue,totalRevenue)+' of total)</li>';}
if(regEntries.length>0&&revenueCol){var topReg=regEntries[0];html+='<li style="font-size:13px;color:#333;margin-bottom:8px;line-height:1.6;">Highest revenue region: <strong>'+topReg.name+'</strong> — '+fmtRev(topReg.revenue)+' ('+topReg.count+' orders)</li>';}
if(dupCount>0){html+='<li style="font-size:13px;color:#e74c3c;margin-bottom:8px;line-height:1.6;">Warning: '+dupCount+' duplicate rows removed during preprocessing</li>';}
if(quantityCol){html+='<li style="font-size:13px;color:#333;margin-bottom:8px;line-height:1.6;">Total units sold: <strong>'+totalQty+'</strong></li>';}
html+='</ul></div>';
html+='<div style="margin-top:16px;padding-top:16px;border-top:1px solid #eee;text-align:center;"><p style="font-size:12px;color:#aaa;margin:0;">Automatically generated by your n8n Data Analyst Agent</p></div>';
html+='</div></div>';
var topCatName=catEntries.length>0?catEntries[0].name:null;
var topCatPct=catEntries.length>0&&revenueCol?pct(catEntries[0].revenue,totalRevenue):null;
var topRegName=regEntries.length>0?regEntries[0].name:null;
var nl=String.fromCharCode(10);
var summary='Analysis complete! Report saved to Google Drive and emailed to your registered address.'+nl+nl;
summary+='Quick Summary:'+nl;
if(revenueCol&&revenues.length>0){summary+='- Total Revenue: '+fmtRev(totalRevenue)+' | Avg: '+fmtRev(avgRevenue)+' | Median: '+fmtRev(medRevenue)+nl;}
summary+='- Records analyzed: '+cleanRows.length+(dupCount>0?' ('+dupCount+' duplicates removed)':'')+nl;
if(topCatName&&topCatPct)summary+='- Top category: '+topCatName+' ('+topCatPct+' of revenue)'+nl;
if(topRegName&&revenueCol)summary+='- Top region: '+topRegName+' ('+fmtRev(regEntries[0].revenue)+')'+nl;
if(quantityCol)summary+='- Total units sold: '+totalQty+nl;
return [{json:{emailHtml:html,chatSummary:summary,success:true}}];
